"""Pack index.html into ../dashboard_page.h as a gzipped byte array.

Run after editing the dashboard:  python embed.py
"""
import gzip
import os

HERE = os.path.dirname(os.path.abspath(__file__))
html = open(os.path.join(HERE, "index.html"), "rb").read()
gz = gzip.compress(html, compresslevel=9, mtime=0)

rows = [", ".join("0x%02x" % b for b in gz[i:i + 16]) for i in range(0, len(gz), 16)]
out = ("// Generated from dashboard/index.html by dashboard/embed.py. Edit the HTML,\n"
       "// then rerun the script; do not edit this file by hand.\n"
       "#pragma once\n#include <stddef.h>\n#include <stdint.h>\n\n"
       "const uint8_t DASHBOARD_GZ[] = {\n  " + ",\n  ".join(rows) + "\n};\n"
       "const size_t DASHBOARD_GZ_LEN = sizeof(DASHBOARD_GZ);\n")
open(os.path.join(HERE, "..", "dashboard_page.h"), "w", newline="\n").write(out)
print("dashboard_page.h: %d bytes of HTML -> %d gzipped" % (len(html), len(gz)))
